package laravelcrypt

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"strings"
	"testing"
)

// The parts of Laravel that sit on top of the encrypter, produced by the real Laravel classes
// (fixtures/app-vectors.json, regenerated by scripts/generate_app_vectors.php): random keys,
// encrypted cookies, encrypted session payloads and Eloquent encrypted casts. Previous keys
// are covered here too, since cookies and rotated payloads depend on them.

type appVector struct {
	Name          string `json:"name"`
	Cipher        string `json:"cipher"`
	KeyB64        string `json:"key_b64"`
	Key           string `json:"key"`
	CookieName    string `json:"cookie_name"`
	ValueB64      string `json:"value_b64"`
	Attribute     string `json:"attribute"`
	PlaintextB64  string `json:"plaintext_b64"`
	Serialization string `json:"serialization"`
	Token         string `json:"token"`
	InnerB64      string `json:"inner_b64"`
	Payload       string `json:"payload"`
}

type appVectorFile struct {
	KeyB64         string      `json:"key_b64"`
	PreviousKeyB64 string      `json:"previous_key_b64"`
	RandomKeys     []appVector `json:"random_keys"`
	Cookies        []appVector `json:"cookies"`
	Casts          []appVector `json:"casts"`
	Sessions       []appVector `json:"sessions"`
}

func loadAppVectors(t *testing.T) appVectorFile {
	t.Helper()
	data, err := os.ReadFile("fixtures/app-vectors.json")
	if err != nil {
		t.Fatalf("read fixtures/app-vectors.json: %v", err)
	}
	var f appVectorFile
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatalf("parse fixtures/app-vectors.json: %v", err)
	}
	if len(f.RandomKeys) == 0 || len(f.Cookies) == 0 || len(f.Casts) == 0 || len(f.Sessions) == 0 {
		t.Fatal("fixtures/app-vectors.json is incomplete")
	}
	return f
}

// appEnc builds the encrypter of an application using the fixture key, optionally having
// rotated from the previous key.
func appEnc(t *testing.T, f appVectorFile, cipher string, withPrevious bool) *Encrypter {
	t.Helper()
	size := keySize(cipher)
	key := mustB64Decode(t, f.KeyB64)[:size]
	var opts []Option
	if withPrevious {
		opts = append(opts, WithPreviousKeys("base64:"+b64Encode(mustB64Decode(t, f.PreviousKeyB64)[:size])))
	}
	enc, err := New("base64:"+b64Encode(key), cipher, opts...)
	if err != nil {
		t.Fatalf("New(%s): %v", cipher, err)
	}
	return enc
}

func TestRandomKeysWorkWithEveryCipher(t *testing.T) {
	f := loadAppVectors(t)
	if len(f.RandomKeys) < 96 {
		t.Fatalf("only %d random-key vectors", len(f.RandomKeys))
	}
	for _, v := range f.RandomKeys {
		enc, err := New("base64:"+v.KeyB64, v.Cipher)
		if err != nil {
			t.Fatalf("%s: %v", v.Name, err)
		}
		got, err := enc.DecryptString(v.Payload)
		if err != nil || got != string(mustB64Decode(t, v.PlaintextB64)) {
			t.Errorf("%s: got %q, %v", v.Name, got, err)
		}
	}
}

func TestLaravelCookiesDecryptAndValidate(t *testing.T) {
	f := loadAppVectors(t)
	for _, v := range f.Cookies {
		want := string(mustB64Decode(t, v.ValueB64))
		current := appEnc(t, f, v.Cipher, false)
		rotated := appEnc(t, f, v.Cipher, true)

		switch v.Key {
		case "current":
			for _, enc := range []*Encrypter{current, rotated} {
				if got, err := enc.DecryptCookie(v.CookieName, v.Payload); err != nil || got != want {
					t.Errorf("%s: got %q, %v", v.Name, got, err)
				}
			}
		case "previous":
			// Issued before the key was rotated: only an encrypter that knows the old key can
			// read it, because the prefix is bound to the key it was issued with.
			if _, err := current.DecryptCookie(v.CookieName, v.Payload); err == nil {
				t.Errorf("%s: read without the previous key", v.Name)
			}
			if got, err := rotated.DecryptCookie(v.CookieName, v.Payload); err != nil || got != want {
				t.Errorf("%s: with the previous key got %q, %v", v.Name, got, err)
			}
		default:
			t.Fatalf("unknown key %q", v.Key)
		}
	}
}

func TestACookieIsBoundToItsName(t *testing.T) {
	f := loadAppVectors(t)
	var v appVector
	for _, c := range f.Cookies {
		if c.CookieName == "laravel_session" && c.Key == "current" {
			v = c
			break
		}
	}
	enc := appEnc(t, f, v.Cipher, false)
	if _, err := enc.DecryptCookie("laravel_session", v.Payload); err != nil {
		t.Fatal(err)
	}
	if _, err := enc.DecryptCookie("XSRF-TOKEN", v.Payload); !errors.Is(err, ErrInvalidCookie) {
		t.Errorf("another cookie name: err = %v, want ErrInvalidCookie", err)
	}
	// A payload from EncryptString has no prefix at all; a shorter one cannot hold it.
	for _, plain := range []string{"no prefix here, but long enough to hold one: 0123456789", "short"} {
		p, _ := enc.EncryptString(plain)
		if _, err := enc.DecryptCookie("laravel_session", p); !errors.Is(err, ErrInvalidCookie) {
			t.Errorf("%q: err = %v, want ErrInvalidCookie", plain, err)
		}
	}
	// Decryption errors pass through.
	if _, err := enc.DecryptCookie("laravel_session", "garbage"); !errors.Is(err, ErrInvalidPayload) {
		t.Errorf("garbage: err = %v, want ErrInvalidPayload", err)
	}
}

func TestCookiesRoundTripWithLaravelsLayout(t *testing.T) {
	for _, c := range allCiphers {
		enc := newEnc(t, c)
		for _, tc := range [][2]string{
			{"laravel_session", "abc123"}, {"empty", ""}, {"pipes", "a|b|c"}, {"küche", "Grüße 世界"},
		} {
			payload, err := enc.EncryptCookie(tc[0], tc[1])
			if err != nil {
				t.Fatal(err)
			}
			if got, err := enc.DecryptCookie(tc[0], payload); err != nil || got != tc[1] {
				t.Errorf("%s/%s: got %q, %v", c, tc[0], got, err)
			}

			// The plaintext is a 41-byte prefix (40 lower-case hex characters and "|") plus the value.
			plain, _ := enc.DecryptString(payload)
			if len(plain) != 41+len(tc[1]) || plain[40] != '|' || !strings.HasSuffix(plain, tc[1]) {
				t.Errorf("%s/%s: unexpected plaintext %q", c, tc[0], plain)
			}
			if strings.Trim(plain[:40], "0123456789abcdef") != "" {
				t.Errorf("%s/%s: prefix %q is not lower-case hex", c, tc[0], plain[:40])
			}
		}
	}
}

func TestTheCookiePrefixMatchesLaravels(t *testing.T) {
	// PHP: hash_hmac('sha1', 'laravel_session' . 'v2', str_repeat("\x2b", 32)) . '|'
	enc := newEnc(t, "aes-256-cbc")
	payload, _ := enc.EncryptCookie("laravel_session", "x")
	plain, _ := enc.DecryptString(payload)
	if want := "de34b8b683dec375f8d5c86fc41645c59842c10e|x"; plain != want {
		t.Errorf("plaintext = %q, want %q", plain, want)
	}
}

func TestEloquentEncryptedCastsDecrypt(t *testing.T) {
	f := loadAppVectors(t)
	if len(f.Casts) < 16 {
		t.Fatalf("only %d casts", len(f.Casts))
	}
	for _, v := range f.Casts {
		enc := appEnc(t, f, v.Cipher, false)
		// A cast is Crypt::encryptString() of the value, or of its JSON.
		got, err := enc.DecryptString(v.Payload)
		if err != nil || got != string(mustB64Decode(t, v.PlaintextB64)) {
			t.Errorf("%s: got %q, %v", v.Name, got, err)
		}
	}

	// The JSON casts hold JSON, which any JSON library reads.
	for _, v := range f.Casts {
		if v.Name != "aes-256-cbc/list" {
			continue
		}
		plain, _ := appEnc(t, f, v.Cipher, false).DecryptString(v.Payload)
		var got map[string]any
		if err := json.Unmarshal([]byte(plain), &got); err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(got["y"], []any{1.0, 2.0}) || got["z"] != "ü" {
			t.Errorf("list cast = %#v", got)
		}
	}
}

func TestEncryptedSessionsDecryptToTheSerializedAttributes(t *testing.T) {
	f := loadAppVectors(t)
	seenPHP := false
	for _, v := range f.Sessions {
		enc := appEnc(t, f, v.Cipher, false)

		// session.encrypt stores Crypt::encrypt() of the already serialized attributes, so the
		// value Laravel decrypts to is a string holding the PHP (or JSON) serialization.
		got, err := enc.Decrypt(v.Payload)
		inner, ok := got.(string)
		if err != nil || !ok || inner != string(mustB64Decode(t, v.InnerB64)) {
			t.Fatalf("%s: got %#v, %v", v.Name, got, err)
		}

		switch v.Serialization {
		case "php":
			seenPHP = true
			attrs, err := PHPUnserialize(inner)
			if err != nil {
				t.Fatalf("%s: %v", v.Name, err)
			}
			m := attrs.(map[string]any)
			cart := m["cart"].(map[string]any)
			if m["user_id"] != int64(7) || m["name"] != "Grüße" || cart["apple"] != int64(2) || m["_token"] != v.Token {
				t.Errorf("%s: attributes = %#v", v.Name, m)
			}

			// ...and writes back what Laravel reads.
			again, err := PHPSerialize(attrs)
			if err != nil {
				t.Fatal(err)
			}
			back, err := PHPUnserialize(again)
			if err != nil || !reflect.DeepEqual(back, attrs) {
				t.Errorf("%s: re-serialized attributes differ: %v", v.Name, err)
			}
		case "json":
			var m map[string]any
			if err := json.Unmarshal([]byte(inner), &m); err != nil || m["user_id"] != 7.0 || m["_token"] != v.Token {
				t.Errorf("%s: attributes = %#v, %v", v.Name, m, err)
			}
		default:
			t.Fatalf("unknown serialization %q", v.Serialization)
		}
	}
	if !seenPHP {
		t.Error("no PHP-serialized session fixture")
	}
}

// --- previous keys ---

func TestRotatedPayloadsDecryptWithPreviousKeys(t *testing.T) {
	vf := loadVectors(t)
	if len(vf.Rotated) < 4 {
		t.Fatalf("only %d rotated fixtures", len(vf.Rotated))
	}
	for _, v := range vf.Rotated {
		size := keySize(v.Cipher)
		current := fixtureEncrypter(t, vf, v.Cipher)
		if _, err := current.DecryptString(v.Payload); err == nil {
			t.Errorf("%s: decrypted without the previous key", v.Name)
		}
		previous := "base64:" + b64Encode(mustB64Decode(t, vf.PreviousKeyB64)[:size])
		rotated, err := New("base64:"+b64Encode(mustB64Decode(t, vf.KeyB64)[:size]), v.Cipher, WithPreviousKeys(previous))
		if err != nil {
			t.Fatal(err)
		}
		got, err := rotated.DecryptString(v.Payload)
		if err != nil || got != string(mustB64Decode(t, v.PlaintextB64)) {
			t.Errorf("%s: got %q, %v", v.Name, got, err)
		}
	}
}

func TestPreviousKeys(t *testing.T) {
	for _, c := range allCiphers {
		old := newEncWithKey(t, c, 0x01)
		older := newEncWithKey(t, c, 0x02)
		currentOnly := newEncWithKey(t, c, 0x03)
		rotated, err := New("base64:"+b64Encode(rawKey(c, 0x03)), c, WithPreviousKeys(
			"base64:"+b64Encode(rawKey(c, 0x01)), "base64:"+b64Encode(rawKey(c, 0x02))))
		if err != nil {
			t.Fatal(err)
		}

		for _, legacy := range []*Encrypter{old, older} {
			payload := mustEncrypt(t, legacy, "legacy")
			if _, err := currentOnly.DecryptString(payload); err == nil {
				t.Errorf("%s: current key alone read a legacy payload", c)
			}
			if got, err := rotated.DecryptString(payload); err != nil || got != "legacy" {
				t.Errorf("%s: rotated got %q, %v", c, got, err)
			}
		}

		// New payloads use the current key only.
		fresh := mustEncrypt(t, rotated, "fresh")
		if got, err := currentOnly.DecryptString(fresh); err != nil || got != "fresh" {
			t.Errorf("%s: fresh payload not readable with the current key: %q %v", c, got, err)
		}
		if _, err := old.DecryptString(fresh); err == nil {
			t.Errorf("%s: fresh payload readable with a previous key", c)
		}

		// An unrelated key is still rejected, and so is tampering.
		if _, err := rotated.DecryptString(mustEncrypt(t, newEncWithKey(t, c, 0x09), "x")); err == nil {
			t.Errorf("%s: unrelated key accepted", c)
		}
		bad := editPayload(t, mustEncrypt(t, old, "legacy"), func(m map[string]any) { m["value"] = flipFirst(m["value"].(string)) })
		if _, err := rotated.DecryptString(bad); err == nil {
			t.Errorf("%s: tampered legacy payload accepted", c)
		}
	}
}

func TestPreviousKeysMustFitTheCipher(t *testing.T) {
	key := "base64:" + b64Encode(rawKey("aes-256-cbc", 1))
	if _, err := New(key, "aes-256-cbc", WithPreviousKeys("base64:"+b64Encode(make([]byte, 16)))); !errors.Is(err, ErrUnsupportedCipher) {
		t.Errorf("16-byte previous key: err = %v, want ErrUnsupportedCipher", err)
	}
	if _, err := New(key, "aes-256-cbc", WithPreviousKeys("")); !errors.Is(err, ErrEmptyKey) {
		t.Errorf("empty previous key: err = %v, want ErrEmptyKey", err)
	}
	if enc, err := New(key, "aes-256-cbc", WithPreviousKeys()); err != nil || len(enc.previous) != 0 {
		t.Errorf("no previous keys: %v", err)
	}
}

func TestPHPSerializeWrappers(t *testing.T) {
	s, err := PHPSerialize(map[string]any{"a": int64(1)})
	if err != nil || s != `a:1:{s:1:"a";i:1;}` {
		t.Fatalf("PHPSerialize = %q, %v", s, err)
	}
	if v, err := PHPUnserialize(s); err != nil || !reflect.DeepEqual(v, map[string]any{"a": int64(1)}) {
		t.Fatalf("PHPUnserialize = %#v, %v", v, err)
	}
	if _, err := PHPSerialize(make(chan int)); err == nil {
		t.Error("PHPSerialize of a channel must fail")
	}
	if _, err := PHPUnserialize("N;N;"); err == nil {
		t.Error("PHPUnserialize must reject trailing data")
	}
}
